/// Executes a single step with retry logic and logging.
async fn execute_step_with_retry<F, Fut>(
    config: &mut StepConfig,
    func_name: &'static str,
    executor: F,
) -> Result<String, Box<dyn std::error::Error>>
where
    F: Fn(&StepConfig) -> Fut + Clone,
    Fut: Future<Output = Result<String, Box<dyn std::error::Error>>> + Send,
{
    let start_time = Instant::now();

    log::info!("[{}] Starting execution. Retry count: {}", config.name, config.retry_count);

    loop {
        match executor(config).await {
            Ok(output) => {
                log::info!(
                    "[{}] Success after {} attempts in {:?}", 
                    func_name, 
                    config.retry_count + 1, 
                    start_time.elapsed()
                );

                // Update state: The output of this step becomes the input for the next (or final result)
                config.current_output = Some(output.clone());
                config.status = StepStatus::Success;

                return Ok(output);
            }
            Err(e) => {
                log::warn!(
                    "[{}] Failed: {}. Retrying... (Attempt: {} / Max: {})", 
                    func_name, e, config.retry_count + 1, config.max_retries
                );

                if config.retry_count >= config.max_retries {
                    log::error!("[{}] Max retries exceeded. Giving up.", func_name);
                    config.status = StepStatus::Failed(e.to_string());
                    return Err(e);
                }

                // Exponential backoff: 1s, 2s, 4s...
                let delay = Duration::from_secs(2u64.pow(config.retry_count));
                log::info!("[{}] Waiting for {} seconds before retry.", func_name, delay.as_secs());

                tokio::time::sleep(delay).await;
                config.retry_count += 1;
            }
        }
    }
}

