        "https://huggingface.co/api/datasets/{}/tree/{}", 
        repo_id, filename
    );

    // Fetch file info from API
    let response: Value = client.get(&api_url).send().await?;

    if !response.is_array() {
        return Err("API returned unexpected format".into());
    }

    // Hugging Face tree endpoint returns an array of files. 
    // We need to find the specific file we want and get its direct URL.
    let file_info = response.get(0)
        .and_then(|v| v.as_object())
        .ok_or("No file info found")?;

    let url = file_info.get("url")
        .and_then(|v| v.as_str())
        .ok_or("Direct URL not found in API response")?;

    // Now download using the direct URL obtained from the API
    let mut resp = client.get(url).send().await?;

    if !resp.status().is_success() {
        return Err(format!("Download failed with status: {}", resp.status()).into());
    }

    let content_length: u64 = resp.content_length().unwrap_or(0);
    fs::create_dir_all(local_dir)?;
    let target_path = local_dir.join(filename);

    let mut file = File::create(&target_path)?;
    let mut total_bytes_read = 0u64;

    while let Some(chunk) = resp.chunk().await? {
        file.write_all(&chunk)?;
        total_bytes_read += chunk.len() as u64;
    }

    drop(file);

    Ok(ModelDownloadStatus::Completed(target_path))
}
